  "1 · First steps": { es: "1 · Primeros pasos", ar: "1 · الخطوات الأولى", zh: "1 · 起步", sw: "1 · Hatua za kwanza", sv: "1 · Första stegen", de: "1 · Erste Schritte", pt: "1 · Primeiros passos", fr: "1 · Premiers pas" },
