  "Normal Go": { es: "Go normal", ar: "غو عادي", zh: "普通围棋", sw: "Go ya kawaida", sv: "Vanlig go", de: "Normales Go", pt: "Go normal", fr: "Go normal" },
  "Capture game (first capture wins)": { es: "Juego de captura (gana la primera captura)", ar: "لعبة الأسر (الأسر الأول يفوز)", zh: "吃子游戏（先提子者胜）", sw: "Mchezo wa kuteka (anayeteka kwanza anashinda)", sv: "Fångstspel (första fångst vinner)", de: "Schlagspiel (erster Schlag gewinnt)", pt: "Jogo de captura (a primeira captura vence)", fr: "Jeu de capture (la première capture gagne)" },
  "Handicap": { es: "Hándicap", ar: "الإعاقة (هانديكاب)", zh: "让子", sw: "Faida ya mawe", sv: "Handikapp", de: "Vorgabe", pt: "Handicap", fr: "Handicap" },
  "2 stones": { es: "2 piedras", ar: "حجران", zh: "2 子", sw: "Mawe 2", sv: "2 stenar", de: "2 Steine", pt: "2 pedras", fr: "2 pierres" },
