  "▶ New game": { es: "▶ Partida nueva", ar: "▶ مباراة جديدة", zh: "▶ 新对局", sw: "▶ Mchezo mpya", sv: "▶ Nytt parti", de: "▶ Neue Partie", pt: "▶ Nova partida", fr: "▶ Nouvelle partie" },
