  "💡 Advice for my next move": { es: "💡 Consejo para mi siguiente jugada", ar: "💡 نصيحة لنقلتي التالية", zh: "💡 给我下一步的建议", sw: "💡 Ushauri kwa hatua yangu inayofuata", sv: "💡 Råd om mitt nästa drag", de: "💡 Rat für meinen nächsten Zug", pt: "💡 Conselho para minha próxima jogada", fr: "💡 Conseil pour mon prochain coup" },
  "🔍 Feedback on my last move": { es: "🔍 Opinión sobre mi última jugada", ar: "🔍 تقييم لنقلتي الأخيرة", zh: "🔍 点评我上一步", sw: "🔍 Maoni kuhusu hatua yangu ya mwisho", sv: "🔍 Återkoppling på mitt senaste drag", de: "🔍 Feedback zu meinem letzten Zug", pt: "🔍 Comentário sobre minha última jogada", fr: "🔍 Avis sur mon dernier coup" },
  "📊 Who is ahead?": { es: "📊 ¿Quién va ganando?", ar: "📊 من المتقدم؟", zh: "📊 谁领先？", sw: "📊 Nani yuko mbele?", sv: "📊 Vem leder?", de: "📊 Wer liegt vorn?", pt: "📊 Quem está na frente?", fr: "📊 Qui mène ?" },
  "💡 Advice": { es: "💡 Consejo", ar: "💡 نصيحة", zh: "💡 建议", sw: "💡 Ushauri", sv: "💡 Råd", de: "💡 Rat", pt: "💡 Conselho", fr: "💡 Conseil" },
